import kotlin.math.min

/**
 * Standard automotive symbols from Pictogrammers Material Design Icons.
 * The selected SVG paths are Apache-2.0 licensed and kept locally so the
 * dashboard does not pull a multi-megabyte icon dependency.
 */
@Composable
internal fun IndicatorSymbol(
    indicator: VehicleIndicator,
    tint: Color,
    modifier: Modifier = Modifier,
) {
    val pathData = mdiPathData[indicator]
    val path = remember(pathData) {
        pathData?.let(PathParser::createPathFromPathData)?.asComposePath()
    }
    Canvas(
        modifier = modifier.semantics {
            contentDescription = indicator.description
        },
    ) {
        if (indicator == VehicleIndicator.STOP) {
            val paint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
                color = tint.toAndroidColor()
                textSize = size.minDimension * 0.29f
                textAlign = Paint.Align.CENTER
                typeface = Typeface.create(Typeface.DEFAULT, Typeface.BOLD)
            }
            val baseline = size.height / 2f - (paint.ascent() + paint.descent()) / 2f
            drawContext.canvas.nativeCanvas.drawText(
                "STOP",
                size.width / 2f,
                baseline,
                paint,
            )
            return@Canvas
        }
        if (path == null) return@Canvas
        val side = min(size.width, size.height)
        val scale = side / 24f
        val left = (size.width - side) / 2f
        val top = (size.height - side) / 2f
        withTransform({
            translate(left, top)
            scale(scale, scale, pivot = Offset.Zero)
            if (indicator == VehicleIndicator.REAR_FOG) {
                scale(-1f, 1f, pivot = Offset(12f, 12f))
            }
        }) {
            drawPath(path = path, color = tint)
        }
    }
}

